WITH filtered_inventory AS (SELECT * FROM inventory WHERE quantity <> 188), inventory_stats AS (SELECT CASE WHEN quantity >= 228 THEN 'high' WHEN quantity >= 100 THEN 'mid' ELSE 'low' END AS quantity_bucket, product_id, SUM(quantity) AS total_quantity, MAX(last_restock) AS latest_last_restock FROM filtered_inventory GROUP BY CASE WHEN quantity >= 228 THEN 'high' WHEN quantity >= 100 THEN 'mid' ELSE 'low' END, product_id) SELECT quantity_bucket, product_id, total_quantity, latest_last_restock FROM inventory_stats WHERE total_quantity > 1180
